using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace Ampelum.RecipeExtract;

/// <summary>
/// Recipe extractor: scans a directory of markdown files for fenced csharp blocks tagged with
/// <c>// ampelum:recipe &lt;slug&gt;</c> and emits one <c>&lt;PascalSlug&gt;.g.cs</c> file per
/// recipe under the output directory. Each generated file declares an xUnit <c>[Fact]</c> method
/// whose body is the recipe block.
/// </summary>
public static class Program
{
    public static int Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.Error.WriteLine("usage: Ampelum.RecipeExtract <recipes-dir> <output-dir>");
            return 1;
        }
        var recipesDir = args[0];
        var outDir = args[1];
        Directory.CreateDirectory(outDir);
        var count = Run(recipesDir, outDir);
        Console.WriteLine($"recipes extracted: {count}");
        return 0;
    }

    static readonly Regex TagLine = new(@"^// ampelum:recipe (?<slug>[a-z0-9-]+)\s*$", RegexOptions.Compiled);

    /// <summary>Extracts all tagged fenced-code blocks under <paramref name="recipesDir"/>.</summary>
    /// <param name="recipesDir">Folder containing <c>*.md</c> recipes.</param>
    /// <param name="outDir">Output folder for generated <c>*.g.cs</c> files.</param>
    /// <returns>Number of recipes extracted.</returns>
    public static int Run(string recipesDir, string outDir)
    {
        if (!Directory.Exists(recipesDir)) return 0;
        Directory.CreateDirectory(outDir);
        var count = 0;
        foreach (var md in Directory.GetFiles(recipesDir, "*.md"))
        {
            foreach (var (slug, body) in ExtractBlocks(File.ReadAllText(md)))
            {
                var pascal = ToPascal(slug);
                var path = Path.Combine(outDir, pascal + ".g.cs");
                File.WriteAllText(path, Render(pascal, body));
                count++;
            }
        }
        return count;
    }

    /// <summary>Parses fenced csharp blocks; yields (slug, body) tuples.</summary>
    public static IEnumerable<(string Slug, string Body)> ExtractBlocks(string markdown)
    {
        var lines = markdown.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
        var i = 0;
        while (i < lines.Length)
        {
            if (lines[i].StartsWith("```csharp", StringComparison.Ordinal))
            {
                i++;
                if (i < lines.Length)
                {
                    var m = TagLine.Match(lines[i]);
                    if (!m.Success)
                    {
                        // skip untagged block
                        while (i < lines.Length && !lines[i].StartsWith("```", StringComparison.Ordinal)) i++;
                        i++;
                        continue;
                    }
                    var slug = m.Groups["slug"].Value;
                    i++;
                    var body = new StringBuilder();
                    while (i < lines.Length && !lines[i].StartsWith("```", StringComparison.Ordinal))
                    {
                        body.AppendLine(lines[i]);
                        i++;
                    }
                    yield return (slug, body.ToString());
                    i++;
                }
            }
            else
            {
                i++;
            }
        }
    }

    static string ToPascal(string slug)
    {
        var sb = new StringBuilder();
        var upper = true;
        foreach (var ch in slug)
        {
            if (ch == '-') { upper = true; continue; }
            sb.Append(upper ? char.ToUpper(ch, CultureInfo.InvariantCulture) : ch);
            upper = false;
        }
        return sb.ToString();
    }

    /// <summary>Renders a generated test file for one recipe.</summary>
    public static string Render(string pascal, string body)
    {
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("#nullable enable");
        sb.AppendLine("using SignalGrid.Ampelum;");
        sb.AppendLine("using SignalGrid.Ampelum.Agents;");
        sb.AppendLine("using SignalGrid.Ampelum.Agents.Memory;");
        sb.AppendLine("using SignalGrid.Ampelum.Agents.SpeakerSelectors;");
        sb.AppendLine("using SignalGrid.Ampelum.Audit;");
        sb.AppendLine("using SignalGrid.Ampelum.Budget;");
        sb.AppendLine("using SignalGrid.Ampelum.Caching.Semantic;");
        sb.AppendLine("using SignalGrid.Ampelum.Hooks;");
        sb.AppendLine("using SignalGrid.Ampelum.Metrics;");
        sb.AppendLine("using SignalGrid.Ampelum.Optimizers;");
        sb.AppendLine("using SignalGrid.Ampelum.Persistence;");
        sb.AppendLine("using SignalGrid.Ampelum.RateLimiting;");
        sb.AppendLine("using SignalGrid.Ampelum.Retrieval;");
        sb.AppendLine("using SignalGrid.Ampelum.Routing;");
        sb.AppendLine("using SignalGrid.Ampelum.Testing;");
        sb.AppendLine("using SignalGrid.Ampelum.Exceptions;");
        sb.AppendLine("using Microsoft.Extensions.AI;");
        sb.AppendLine("using Microsoft.Extensions.Logging.Abstractions;");
        sb.AppendLine("using Shouldly;");
        sb.AppendLine("using Xunit;");
        sb.AppendLine("#pragma warning disable AMPELUM_V09_PREVIEW");
        sb.AppendLine();
        sb.AppendLine("namespace Ampelum.Recipes.Tests.Generated;");
        sb.AppendLine();
        sb.AppendLine($"public sealed class {pascal}");
        sb.AppendLine("{");
        sb.AppendLine("    [Fact]");
        sb.AppendLine($"    public async Task Run()");
        sb.AppendLine("    {");
        sb.AppendLine("        var ct = TestContext.Current.CancellationToken;");
        foreach (var line in body.TrimEnd().Split('\n'))
        {
            sb.Append("        ");
            sb.AppendLine(line.TrimEnd('\r'));
        }
        sb.AppendLine("    }");
        sb.AppendLine("}");
        return sb.ToString();
    }
}
